"""The Freeciv variant specs are generated by gen_variants.py from freeciv.yaml.
A variant must not drift from the base spec when only freeciv.yaml is edited."""
import unittest

from polyhost.res.overlay_sources.freeciv import gen_variants


class FreecivVariantSpecsTest(unittest.TestCase):

    def test_the_committed_variant_specs_match_gen_variants(self):
        for name in gen_variants.VARIANTS:
            with self.subTest(spec=name):
                committed = (gen_variants.HERE / name).read_text(encoding="utf-8")
                self.assertEqual(committed, gen_variants.render(name),
                                 f"{name} is stale: run "
                                 "python polyhost/res/overlay_sources/freeciv/gen_variants.py")

    def test_a_step_that_names_a_missing_binding_stops_the_script(self):
        base = [{"key": "A", "icon": "a.png", "label": "A"}]
        for op in (("drop", "B", []), ("set", "A", ["SHIFT"], {"label": "x"}),
                   ("keep", [("B", [])])):
            with self.subTest(op=op[0]):
                with self.assertRaises(SystemExit):
                    gen_variants.apply(base, [op])
        with self.assertRaises(SystemExit):
            gen_variants.apply(base, [("add", {"key": "a", "icon": "b.png", "label": "B"})])


if __name__ == "__main__":
    unittest.main()
